                            workspace: owner,
                            repository: repo,
                            jobId: jobIdMatch[1]
                        });
                    }
                    var logs = rawLogs;
                    if (typeof rawLogs === 'string') {
                        try {
                            var parsed = JSON.parse(rawLogs);
                            if (parsed && parsed.result) logs = parsed.result;
                        } catch (e) { /* use as-is */ }
                    }
                    appendLog(check, logs, 'Error log');
                } catch (e) {
                    console.warn('Could not fetch logs for job', jobIdMatch[1], ':', e.message || e);
                }
            }

