                try {
                    getTracker().linkIssues(ticketKey, newKey, 'is blocked by');
                    console.log('  🔗 Linked ' + ticketKey + ' is blocked by ' + newKey);
                } catch (e) {
                    console.warn('  ⚠️  Failed to link ' + newKey + ' to ' + ticketKey + ': ' + (e.message || e));
                }
