            (ticketKey ? '*Ticket:* [' + ticketKey + ']\n' : '') +
            '*Workflow:* ' + runWorkflow + '\n' +
            '*Run:* ' + run.name + ' #' + run.run_number + '\n' +
            '*Branch:* ' + (run.head_branch || 'unknown') + '\n' +
            '*Commit:* ' + (run.head_sha ? run.head_sha.substring(0, 7) : 'unknown') + '\n' +
            '*URL:* ' + run.html_url + '\n' +
            '*Run ID:* ' + runId;

