                        rawLogs = scm.getJobLogs(jobIdMatch[1]);
                    } else {
                        rawLogs = github_get_job_logs({
                            workspace: owner,
                            repository: repo,
                            jobId: jobIdMatch[1]
                        });
                    }
                    var logs = rawLogs;
                    if (typeof rawLogs === 'string') {
                        try {
                            var parsed = JSON.parse(rawLogs);
                            if (parsed && parsed.result) logs = parsed.result;
                        } catch (e) { /* use as-is */ }
                    }
