                        if (urlMatch) newKey = urlMatch[1];
                    }
                } else if (result.key) {
                    newKey = result.key;
                }
            }

            if (!newKey) {
                console.warn('  ⚠️  Bug created but no key returned for run ' + runId + ' (result: ' + result + ')');
                created++;
                continue;
            }

