                newKey = result.key;
            }
        }

        if (!newKey) {
            console.warn('  ⚠️  Bug created but no key returned for run ' + runId + ' (result: ' + result + ')');
            created++;
            continue;
        }

        // 5. Add idempotency label
        try {
            getTracker().addLabel(newKey, label);
        } catch (e) {
            console.warn('  ⚠️  Failed to add label ' + label + ' to ' + newKey + ': ' + (e.message || e));
        }

