                        if (parsedJenkinsLogs && parsedJenkinsLogs.result) jenkinsLogs = parsedJenkinsLogs.result;
                    } catch (e) { /* keep raw string */ }
                }
                appendLog(check, jenkinsLogs, 'Jenkins error log');
