   } catch (e) {
       console.warn(' ⚠️ JQL search failed for run ' + runId + ': ' + (e.message || e));
   }
   if (existing.length > 0) {
       console.log(' ⏭️ Run ' + runId + ' — bug already exists (' + existing[0].key + '), skipping');
