       } catch (e) {
           console.warn(' ⚠️ Failed to add ci-ticket label to ' + newKey + ': ' + (e.message || e));
       }
   }

   console.log(' ✅ Created ' + newKey + ' for run ' + runId);
   return { status: 'created', key: newKey };
}
