       return { status: 'created_keyless' };
   }

   try {
       tracker.addLabel(newKey, label);
   } catch (e) {
       console.warn(' ⚠️ Failed to add label ' + label + ' to ' + newKey + ': ' + (e.message || e));
   }

   if (ticketKey) {
