    test('returns null when no shape matches', function() {
        assert.equal(load().extractCreatedTicketKey({ id: '5' }), null);
        assert.equal(load().extractCreatedTicketKey('🚨 boom'), null);
        assert.equal(load().extractCreatedTicketKey(42), null);
    });
});

