function extractKeyFromString(result) {
   var newKey = null;
   try {
       var parsed = JSON.parse(result);
       if (parsed && parsed.key) newKey = parsed.key;
   } catch (e) {}
   if (!newKey && /^[A-Za-z0-9_-]+$/.test(result.trim())) newKey = result.trim();
   if (!newKey) {
       var urlMatch = result.match(/\/browse\/([A-Z]+-\d+)/);
