       var openBug = [];
       try {
           openBug = tracker.searchIssues('project = ' + jiraProject + ' AND issuetype = Bug AND labels = "' + ticketLabel + '" AND statusCategory != Done', { fields: ['key', 'status'] }) || [];
       } catch (e) {
           console.warn(' ⚠️ JQL search for open ticket bug failed: ' + (e.message || e));
       }
