    var md = '# ⚠️ Failed CI Checks — Fix Before Completing Rework\n\n';
    md += 'Full (untruncated) logs are available in `ci_failures_full.log`.\n\n';
    md += failedChecks.length + ' check(s) failed on commit `' + headSha.substring(0, 8) + '`:\n\n';
