suite('githubHelpers.detectFailedChecks — pure log helpers (gh-1012)', function() {

    function makeGh(mocks) {
        return loadGithubHelpers(mocks || {});
    }

    test('parseCheckRunsResult normalizes every accepted payload shape', function() {
        var gh = makeGh();
