        var outcome = processFailedRun(runs[i], {
            tracker: getTracker(),
            jiraProject: jiraProject,
            workflowId: workflowId
        });
        if (outcome.status === 'skipped_existing' || outcome.status === 'skipped_open_bug') {
            skipped++;
