    if (openBug.length > 0) {
        console.log('  ⏭️  ' + ticketKey + ' — open bug already exists (' + openBug[0].key + '), skipping run ' + runId);
        return { status: 'skipped_open_bug' };
    }
    return { ticketKey: ticketKey };
}

