function checkRunDedup(run, tracker, jiraProject) {
    var runId = run.id;
    var label = 'ci-run-' + runId;

    var existing = searchBugsOrEmpty(tracker,
        'project = ' + jiraProject + ' AND issuetype = Bug AND labels = "' + label + '"',
        ['key'], '  ⚠️  JQL search failed for run ' + runId + ': ');

